#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

int main() {
    int totalLines;
    std::cin >> totalLines;
    std::cin.ignore(); // ignore the remaining newline after reading totalLines
    std::string inputString;
    std::getline(std::cin, inputString);

    // Split inputString by pattern "\\(.*?\\)"
    // Since C++ doesn't have built-in regex split, we'll manually extract segments
    std::vector<std::string> segments;
    size_t start = 0;
    size_t pos = 0;
    while ((pos = inputString.find('(', start)) != std::string::npos) {
        size_t endPos = inputString.find(')', pos);
        if (endPos == std::string::npos) {
            break; // no matching closing parenthesis
        }
        // segment before '('
        if (pos > start) {
            segments.push_back(inputString.substr(start, pos - start));
        }
        start = endPos + 1;
    }
    // add remaining part after last ')'
    if (start < inputString.size()) {
        segments.push_back(inputString.substr(start));
    }

    int maxLen = 0;
    for (const auto& segment : segments) {
        std::stringstream ss(segment);
        std::string token;
        while (std::getline(ss, token, '_')) {
            if (token.length() > maxLen) {
                maxLen = token.length();
            }
        }
    }

    // Find enclosed texts within parentheses
    std::vector<std::string> enclosedTexts;
    int startIdx = -1;
    for (size_t i = 0; i < inputString.length(); ++i) {
        if (inputString[i] == '(') {
            startIdx = i;
        } else if (inputString[i] == ')' && startIdx != -1) {
            enclosedTexts.push_back(inputString.substr(startIdx + 1, i - startIdx - 1));
            startIdx = -1;
        }
    }

    int wordCount = 0;
    for (const auto& enclosed : enclosedTexts) {
        std::stringstream ss(enclosed);
        std::string word;
        while (std::getline(ss, word, '_')) {
            if (!word.empty()) {
                ++wordCount;
            }
        }
    }

    std::cout << maxLen << " " << wordCount << std::endl;

    return 0;
}
